#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int x;
    struct Node *next;
} Node;

Node *new_node(int x) {
    Node *p = (Node *)malloc(sizeof(Node));
    if (p == NULL) {
        return NULL;
    }
    p->x = x;
    p->next = NULL;
    return p;
}

Node *push_front(Node *head, int x) {
    Node *p = new_node(x);
    if (p == NULL) {
        return head;
    }
    p->next = head;
    return p;
}

int list_len(Node *head) {
    int cnt = 0;
    Node *cur = head;
    while (cur != NULL) {
        cnt = cnt + 1;
        cur = cur->next;
    }
    return cnt;
}

void print_list(Node *head) {
    Node *cur = head;
    while (cur != NULL) {
        printf("%d -> ", cur->x);
        cur = cur->next;
    }
    printf("NULL\n");
}

void free_list(Node *head) {
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        free(cur);
        cur = next;
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    Node *head = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        if (scanf("%d", &v) != 1) {
            return 1;
        }
        head = push_front(head, v);
    }

    print_list(head);
    printf("链子上有 %d 只环\n", list_len(head));

    free_list(head);
    head = NULL;
    return 0;
}
